def rank_items(scores):
    sorted_scores = sorted(enumerate(scores), key=lambda x: x[1], reverse=True)
    ranks = [0] * len(scores)
    current_rank = 1
    count = 1

    for i in range(len(sorted_scores)):
        if i > 0 and sorted_scores[i][1] == sorted_scores[i - 1][1]:
            count += 1
        else:
            avg_rank = (current_rank + current_rank + count - 1) / 2
            for j in range(i - count, i):
                ranks[sorted_scores[j][0]] = avg_rank
            current_rank += count
            count = 1

    # Handle the last group of ties
    if count > 1:
        avg_rank = (current_rank + current_rank + count - 1) / 2
        for j in range(len(sorted_scores) - count, len(sorted_scores)):
            ranks[sorted_scores[j][0]] = avg_rank

    return ranks

