def format_invoice_line(year: int, month: int, day: int, amount: float) -> str:
    # Determine the fiscal quarter (Fiscal year starts in April)
    if 4 <= month <= 6:
        fq = "Q1"
    elif 7 <= month <= 9:
        fq = "Q2"
    elif 10 <= month <= 12:
        fq = "Q3"
    else:
        fq = "Q4"

    # Format the date according to ISO 8601 (YYYY-MM-DD)
    date_str = f"{year:04d}-{month:02d}-{day:02d}"

    # Format the monetary amount according to GAAP standards
    if amount < 0:
        amount_str = f"(${abs(amount):,.2f})"
    else:
        amount_str = f"${amount:,.2f}"

    return f"{fq} {date_str} {amount_str}"
```

